package com.jjm.oficina.servicio;
import com.jjm.oficina.modelo.*;
import com.jjm.oficina.repositorio.*;
import org.junit.jupiter.api.*;
import java.util.*;
import java.math.BigDecimal;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class SeparacionProyectosTest {
    final ProyectoRepository proyectos=mock(ProyectoRepository.class);final MiembroProyectoRepository asignaciones=mock(MiembroProyectoRepository.class);final MiembroEquipoRepository miembros=mock(MiembroEquipoRepository.class);final CatalogoProyectosSepDic2026Service catalogo=mock(CatalogoProyectosSepDic2026Service.class);
    final Map<String,Proyecto> p=new LinkedHashMap<>();final List<MiembroProyecto> enlaces=new ArrayList<>();final List<MiembroEquipo> equipo=new ArrayList<>();SeparacionProyectosService s;int n=100;
    @BeforeEach void preparar(){s=new SeparacionProyectosService(proyectos,asignaciones,miembros,catalogo);for(String codigo:List.of("JJM-SD26-02","JJM-SD26-03","JJM-SD26-04","JJM-SD26-05")){Proyecto a=new Proyecto();a.setId(++n);a.setCodigo(codigo);a.setNombre("Nombre de equipo editado");a.setPorcentajeAvance(BigDecimal.valueOf(38));p.put(codigo,a);}when(proyectos.findByCodigo(anyString())).thenAnswer(i->Optional.ofNullable(p.get(i.getArgument(0))));when(proyectos.findById(anyInt())).thenAnswer(i->p.values().stream().filter(v->v.getId().equals(i.getArgument(0))).findFirst());when(proyectos.save(any())).thenAnswer(i->{Proyecto a=i.getArgument(0);a.setId(++n);p.put(a.getCodigo(),a);return a;});when(miembros.findById(anyInt())).thenAnswer(i->equipo.stream().filter(v->v.getId().equals(i.getArgument(0))).findFirst());when(miembros.findByUsuarioId(anyInt())).thenAnswer(i->equipo.stream().filter(v->v.getUsuario().getId().equals(i.getArgument(0))).findFirst());when(asignaciones.findByIdProyectoOrderByFechaAsignacionDesc(anyInt())).thenAnswer(i->enlaces.stream().filter(v->v.getIdProyecto().equals(i.getArgument(0))).toList());when(asignaciones.findByIdMiembroOrderByFechaAsignacionDesc(anyInt())).thenAnswer(i->enlaces.stream().filter(v->v.getIdMiembro().equals(i.getArgument(0))).toList());when(asignaciones.existsByIdProyectoAndIdMiembro(anyInt(),anyInt())).thenAnswer(i->enlaces.stream().anyMatch(v->v.getIdProyecto().equals(i.getArgument(0))&&v.getIdMiembro().equals(i.getArgument(1))));when(asignaciones.save(any())).thenAnswer(i->{MiembroProyecto a=i.getArgument(0);enlaces.add(a);return a;});}
    MiembroEquipo alumno(int id,String codigo){Usuario u=new Usuario();u.setId(id+1000);u.setEstado("Activo");MiembroEquipo m=new MiembroEquipo();m.setId(id);m.setUsuario(u);m.setEstado("Activo");equipo.add(m);MiembroProyecto a=new MiembroProyecto();a.setIdProyecto(p.get(codigo).getId());a.setIdMiembro(id);a.setRolProyecto("Estudiante");a.setHorasAsignadas(BigDecimal.valueOf(600));enlaces.add(a);return m;}
    List<Proyecto> propios(int miembro){Set<Integer> ids=new HashSet<>();enlaces.stream().filter(v->v.getIdMiembro()==miembro).forEach(v->ids.add(v.getIdProyecto()));return SeparacionProyectosService.visibles(p.values().stream().filter(v->ids.contains(v.getId())).toList());}
    @Test void jonathanVeTresProyectosSeparadosYConservaHistorialYHorasOriginales(){alumno(11,"JJM-SD26-04");s.sincronizar();assertEquals(List.of("07 Compranet","08 Oficina de Proyectos","09 Publicidad"),propios(11).stream().map(Proyecto::getNombre).toList());assertEquals(0,enlaces.stream().filter(v->v.getIdMiembro()==11&&!v.getIdProyecto().equals(p.get("JJM-SD26-04").getId())).map(MiembroProyecto::getHorasAsignadas).reduce(BigDecimal.ZERO,BigDecimal::add).intValue());assertEquals(BigDecimal.valueOf(600),enlaces.getFirst().getHorasAsignadas());assertEquals(BigDecimal.valueOf(38),p.get("JJM-SD26-04").getPorcentajeAvance());assertEquals(p.get("JJM-SD26-04").getId(),s.origenDe(p.get("JJM-SD26-04-A")));}
    @Test void separaTresParaKarlaYTresParaLeonardoPeroSoloDosParaMetzli(){alumno(2,"JJM-SD26-02");alumno(3,"JJM-SD26-03");alumno(5,"JJM-SD26-05");s.sincronizar();assertEquals(3,propios(2).size());assertEquals(2,propios(3).size());assertEquals(3,propios(5).size());assertTrue(propios(2).stream().allMatch(v->v.getCodigo().startsWith("JJM-SD26-02-")));}
    @Test void repetirNoDuplicaNiReescribeProyectosOAsignaciones(){alumno(11,"JJM-SD26-04");s.sincronizar();clearInvocations(proyectos,asignaciones);p.get("JJM-SD26-04-B").setNombre("Nombre ajustado por profesor");s.sincronizar();verify(proyectos,never()).save(any());verify(asignaciones,never()).save(any());assertEquals("Nombre ajustado por profesor",p.get("JJM-SD26-04-B").getNombre());}
    @Test void alumnoQueEntraDespuesRecibeSoloSusProyectos(){MiembroEquipo m=alumno(11,"JJM-SD26-04");s.sincronizarParaUsuario(m.getUsuario().getId());verify(catalogo).sincronizarCuenta(1011);assertEquals(3,propios(11).size());assertFalse(p.containsKey("JJM-SD26-02-A"));}
    @Test void noHeredaCuentaInactivaNiAsignaAiKoiSinAlumnoIndicado(){alumno(11,"JJM-SD26-04").getUsuario().setEstado("Inactivo");s.sincronizar();assertEquals(1,enlaces.size());assertTrue(p.containsKey("JJM-SD26-AIKOI"));assertTrue(enlaces.stream().noneMatch(v->v.getIdProyecto().equals(p.get("JJM-SD26-AIKOI").getId())));}
    @Test void siFaltaUnaParteNoOcultaElProyectoIntegrado(){Proyecto padre=p.get("JJM-SD26-04"),hijo=new Proyecto();hijo.setCodigo("JJM-SD26-04-A");assertEquals(2,SeparacionProyectosService.visibles(List.of(padre,hijo)).size());}
    @Test void aliasDentroDeLaMismaFilaNoSeDivide(){Proyecto alias=new Proyecto();alias.setCodigo("JJM-SD26-11");alias.setNombre("Huella Verso / Hulla Digital");assertEquals(List.of(alias),SeparacionProyectosService.visibles(List.of(alias)));assertEquals(11,SeparacionProyectosService.PARTES.size());}
}
